mapper.select:
SELECT o.id, o.order_no, o.warehouse_id, w.name AS warehouse_name, o.customer_id, o.customer_name, o.receive_address, o.expect_ship_time, o.status, o.total_qty, o.allocated_qty, o.picked_qty, o.allocate_time, o.remark, o.create_time, o.update_time FROM outbound_order o LEFT JOIN warehouse w ON w.id = o.warehouse_id AND w.deleted = 0 WHERE o.deleted = 0
AND (o.order_no LIKE CONCAT('%', #{query.keyword}, '%') OR o.customer_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND o.warehouse_id = #{query.warehouseId}
AND o.status = #{query.status}
AND o.create_time >= #{query.beginTime}
AND o.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY (o.status IN ('SHIPPED','REVERSED','CLOSED','CANCELLED')) ASC, o.id DESC

mapper.update:
UPDATE outbound_order
SET status    = 'PICKING',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'ALLOCATED'
  AND deleted = 0

UPDATE outbound_order
SET status    = 'SHIPPED',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'PICKED'
  AND deleted = 0

UPDATE outbound_order
SET status    = 'CANCELLED',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'CREATED'
  AND deleted = 0
